/* Image Library Layout */
.image-library {
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 20px;
}

.library-header {
    text-align: center;
    margin-bottom: 50px;
}

.library-header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 10px;
    background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.subtitle {
    color: var(--text-secondary);
    font-size: 1.1rem;
}

/* Gallery Grid */
.gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 30px;
}

/* Image Card */
.image-card {
    background: var(--dark-surface);
    border: 1px solid var(--dark-border);
    border-radius: 12px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.image-card:hover {
    border-color: var(--accent-primary);
    box-shadow: 0 10px 30px rgba(59, 130, 246, 0.1);
    transform: translateY(-4px);
}

/* Image Placeholder */
.image-placeholder {
    width: 100%;
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.image-icon {
    width: 60px;
    height: 60px;
    stroke: rgba(255, 255, 255, 0.3);
    stroke-width: 1.5;
}

/* Image Info */
.image-info {
    padding: 20px;
    flex: 1;
}

.image-info h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 5px;
    color: var(--text-primary);
}

.file-size {
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Delete Button (Trigger) */
.delete-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 20px;
    margin: 0 20px 20px 20px;
    background-color: var(--dark-surface-light);
    color: var(--accent-danger);
    border: 1px solid var(--accent-danger);
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition);
}

.delete-btn svg {
    width: 18px;
    height: 18px;
    stroke-width: 2;
