class DeleteDialog {
    constructor() {
        this.dialog = document.getElementById('delete-dialog');
        this.confirmBtn = document.getElementById('confirm-btn');
        this.cancelBtn = document.getElementById('cancel-btn');
        this.closeBtn = document.querySelector('.modal-close');
        this.imageNameElement = document.getElementById('image-name');
        this.triggers = document.querySelectorAll('.trigger');

        this.currentImageId = null;
        this.currentImageName = null;

        this.init();
    }

    init() {
        // Attach click handlers to all trigger buttons
        this.triggers.forEach(trigger => {
            trigger.addEventListener('click', (e) => this.handleTriggerClick(e));
        });

        // Attach handlers to dialog controls
        this.confirmBtn.addEventListener('click', () => this.handleConfirm());
        this.cancelBtn.addEventListener('click', () => this.handleCancel());
        this.closeBtn.addEventListener('click', () => this.handleCancel());

        // Close dialog when clicking outside (on the overlay)
        this.dialog.addEventListener('click', (e) => {
            if (e.target === this.dialog) {
                this.handleCancel();
            }
        });

        // Close dialog on Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.isOpen()) {
                this.handleCancel();
            }
        });
    }

    handleTriggerClick(e) {
        e.preventDefault();
        const button = e.currentTarget;
        const imageId = button.getAttribute('data-image-id');
        const imageCard = button.closest('.image-card');
        const imageName = imageCard.querySelector('.image-info h3').textContent;

        this.currentImageId = imageId;
        this.currentImageName = imageName;

        // Update dialog with image name
        this.imageNameElement.textContent = imageName;

        this.open();
    }

    handleConfirm() {
        if (this.currentImageId && this.currentImageName) {
            console.log(`Deleting image: ${this.currentImageName} (ID: ${this.currentImageId})`);

            // Simulate deletion with visual feedback
            const imageCard = document.querySelector(`[data-image-id="${this.currentImageId}"]`).closest('.image-card');
            imageCard.style.opacity = '0.5';
            imageCard.style.pointerEvents = 'none';

            // Show success feedback
            this.showDeleteSuccess();

            // Close dialog
            this.close();

            // Reset after delay
            setTimeout(() => {
                imageCard.style.opacity = '1';
                imageCard.style.pointerEvents = 'auto';
            }, 1000);
        }
    }

    handleCancel() {
        this.close();
    }

    open() {
        this.dialog.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }

    close() {
        this.dialog.style.display = 'none';
        document.body.style.overflow = 'auto';
    }

    isOpen() {
        return this.dialog.style.display !== 'none';
    }

    showDeleteSuccess() {
        // Create a temporary toast notification
        const toast = document.createElement('div');
        toast.style.cssText = `
            position: fixed;
            bottom: 24px;
            right: 24px;
            background: linear-gradient(135deg, #10b981 0%, #059669 100%);
            color: white;
            padding: 16px 24px;
            border-radius: 8px;
            box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
            font-weight: 500;
            z-index: 2000;
            animation: slideInUp 0.3s ease-out;
        `;
        toast.textContent = `"${this.currentImageName}" has been deleted`;

        document.body.appendChild(toast);

        setTimeout(() => {
            toast.style.animation = 'slideOutDown 0.3s ease-out';
            setTimeout(() => toast.remove(), 300);
        }, 2000);
    }
}

// Initialize dialog when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        new DeleteDialog();
    });
} else {
    new DeleteDialog();
}
