.image-placeholder {
    width: 100%;
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.image-icon {
    width: 60px;
    height: 60px;
    stroke: rgba(255, 255, 255, 0.3);
    stroke-width: 1.5;
}

