+            color: white;
+            padding: 16px 24px;
+            border-radius: 8px;
+            box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
+            font-weight: 500;
+            z-index: 2000;
+            animation: slideInUp 0.3s ease-out;
+        `;
+        toast.textContent = `"${this.currentImageName}" has been deleted`;
+        
+        document.body.appendChild(toast);
+        
+        setTimeout(() => {
